using System.Collections.Immutable;
using System.Linq;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Diagnostics;
using Cosmos.EffectAlgebra;

namespace Cosmos.EffectAlgebra.Analyzer;

/// <summary>
/// L3 Roslyn Analyzer 骨架（迭代09）。
/// 角色：仅发**根因**诊断，绝不重算代数（net/Peak/Compatible 全在 L1，类型强制）。
/// 控制流近似不变式：本分析为调用级（intra-method）近似；运行期 Σnet（§3.3.1）为权威，
///   编译期静态结果仅作早期根因提示，不得据此声称"数学已验证"（注释明言，避免假绿）。
/// 诊断 id 引 §x.y：EAA0901 = §3.3.1 DO-9 近似泄漏；EAA0801 = §8.3.1 kind 禁止覆盖信息性。
/// 零 Godot 依赖：Godot API 名来自 L1 GodotApiWhitelist / ReleaseClass 数据（§7/§8.1），编译期字符串匹配。
/// </summary>
[DiagnosticAnalyzer(LanguageNames.CSharp)]
public sealed class EffectAlgebraAnalyzer : DiagnosticAnalyzer
{
    // ── §3.3.1 DO-9 近似泄漏：方法内 acquire（create/occupy-create）无对应 release-class 且未标 [EffectOverride] ──
    // 诊断 id EAA0901（"09"=§3.3.1，"01"=DO-9 第 1 个静态近似规则）。
    private static readonly DiagnosticDescriptor MissingReleaseForAcquire = new(
        id: "EAA0901",
        title: "疑似资源泄漏（DO-9 静态近似）",
        messageFormat: "方法 '{0}' 调用了 acquire 类 API（{1}）但无对应 release-class 调用且未标 [EffectOverride]；运行期 Σnet 可能泄漏（§3.3.1 DO-9）。此为控制流近似，运行期 net 为权威。",
        category: "EffectAlgebra",
        defaultSeverity: DiagnosticSeverity.Warning,
        isEnabledByDefault: true,
        description: "§3.3.1 DO-9 + §8.1 release-class：acquire（AddChild/Instantiate/Connect/...）须配 release-class（QueueFree/RemoveChild/Disconnect/...）。L3 仅做调用级近似；真实闭合由运行期 net 判定。");

    // ── §8.3.1 kind 禁止覆盖：用户若在 [EffectOverride] 写 kind/OverrideKind 命名参数 ⇒ 信息性（类型层已禁止）──
    // 诊断 id EAA0801（"08"=§8.3，"01"=第 1 条）。L1 EffectOverrideAttribute 无 OverrideKind 属性 ⇒ 正常不会触发，
    //   此处作静态护栏：若源码仍出现该命名参数（编译期已非法），提示用户删除（类型层即禁止 read/write/occupy 互转）。
    private static readonly DiagnosticDescriptor EffectOverrideKindForbidden = new(
        id: "EAA0801",
        title: "[EffectOverride] 禁止覆盖 kind（§8.3.1）",
        messageFormat: "[EffectOverride] 不得指定 kind/OverrideKind 覆盖（类型层已禁止 kind 互转，§8.3.1）；请删除该命名参数。",
        category: "EffectAlgebra",
        defaultSeverity: DiagnosticSeverity.Info,
        isEnabledByDefault: true,
        description: "§8.3.1：override 仅可覆盖 mode/size/scope，禁止覆盖 kind（read/write/occupy 互转）。L1 类型不提供 OverrideKind ⇒ 类型强制。");

    public override ImmutableArray<DiagnosticDescriptor> SupportedDiagnostics { get; } =
        ImmutableArray.Create(MissingReleaseForAcquire, EffectOverrideKindForbidden);

    // 预先从 L1 数据计算 canonical 名集合（控制流近似匹配用，零 Godot 依赖）。
    // Acquire：§7 白名单中任一 Claim 为 Mode.Create（含 Occupy+Create）的 API。
    // Release：§7 中任一 Claim 为 Mode.Release 的 API，并并上 §8.1 release-class（queue_free/... 等）。
    private static readonly ImmutableHashSet<string> AcquireApiNames = BuildAcquireNames();
    private static readonly ImmutableHashSet<string> ReleaseApiNames = BuildReleaseNames();

    private static string Canonical(string name) =>
        name.ToLowerInvariant().Replace(".", "").Replace("_", "");

    private static ImmutableHashSet<string> BuildAcquireNames()
    {
        var set = ImmutableHashSet.CreateBuilder<string>();
        foreach (var m in GodotApiWhitelist.All)
            if (m.Claims.Any(c => c.Mode == Mode.Create))
                set.Add(Canonical(m.GodotApi));
        return set.ToImmutable();
    }

    private static ImmutableHashSet<string> BuildReleaseNames()
    {
        var set = ImmutableHashSet.CreateBuilder<string>();
        foreach (var m in GodotApiWhitelist.All)
            if (m.Claims.Any(c => c.Mode == Mode.Release))
                set.Add(Canonical(m.GodotApi));
        // §8.1 release-class：Godot 方法名（snake_case 源）规范化为 C# PascalCase 匹配键。
        foreach (var r in ReleaseClass.Names)
            set.Add(Canonical(r));
        return set.ToImmutable();
    }

    public override void Initialize(AnalysisContext context)
    {
        context.ConfigureGeneratedCodeAnalysis(GeneratedCodeAnalysisFlags.None);
        context.EnableConcurrentExecution();
        // §3.3.1 DO-9 / §8.3.1：以方法声明为分析单元（控制流近似：仅方法内调用可见性）。
        context.RegisterSyntaxNodeAction(AnalyzeMethod, SyntaxKind.MethodDeclaration);
    }

    private static void AnalyzeMethod(SyntaxNodeAnalysisContext context)
    {
        var method = (MethodDeclarationSyntax)context.Node;

        // ── §8.3.1 信息性护栏：解析 [EffectOverride] 命名参数 ──
        foreach (var attr in method.AttributeLists.SelectMany(l => l.Attributes))
        {
            var attrName = attr.Name.ToString();
            if (IsEffectOverride(attrName))
            {
                foreach (var arg in attr.ArgumentList?.Arguments ?? default)
                {
                    var named = arg.NameEquals?.Name.Identifier.ValueText;
                    if (named == "kind" || named == "OverrideKind")
                    {
                        context.ReportDiagnostic(Diagnostic.Create(
                            EffectOverrideKindForbidden, attr.GetLocation()));
                    }
                }
            }
        }

        // 方法已标 [EffectOverride] / [AcceptDeviation] ⇒ 逃逸通道已声明，跳过 DO-9 近似泄漏（§8.3）。
        bool hasEscape = method.AttributeLists.SelectMany(l => l.Attributes)
            .Any(a => IsEffectOverride(a.Name.ToString()) || IsAcceptDeviation(a.Name.ToString()));
        if (hasEscape) return;

        // 收集方法体内所有调用表达式（控制流近似：不展开被调用方法内部）。
        var invocations = method.DescendantNodes()
            .OfType<InvocationExpressionSyntax>();

        bool hasAcquire = false;
        bool hasRelease = false;
        var firstAcquire = "";
        foreach (var inv in invocations)
        {
            var canon = CanonicalOfInvocation(inv);
            if (AcquireApiNames.Contains(canon))
            {
                hasAcquire = true;
                if (firstAcquire.Length == 0) firstAcquire = RawName(inv);
            }
            if (ReleaseApiNames.Contains(canon)) hasRelease = true;
        }

        // §3.3.1 DO-9 近似：acquire 且无 release ⇒ 疑似泄漏（运行期 net 为权威，见类注释）。
        if (hasAcquire && !hasRelease)
        {
            context.ReportDiagnostic(Diagnostic.Create(
                MissingReleaseForAcquire,
                method.Identifier.GetLocation(),
                method.Identifier.Text,
                firstAcquire));
        }
    }

    // 调用的 canonical 键：成员访问 "Audio.Play" ⇒ "audioplay"；裸 "AddChild" ⇒ "addchild"。
    private static string CanonicalOfInvocation(InvocationExpressionSyntax inv) =>
        Canonical(RawName(inv));

    private static string RawName(InvocationExpressionSyntax inv)
    {
        return inv.Expression switch
        {
            MemberAccessExpressionSyntax ma => ma.Expression.ToString() + "." + ma.Name.Identifier.Text,
            IdentifierNameSyntax id => id.Identifier.Text,
            _ => inv.Expression.ToString()
        };
    }

    private static bool IsEffectOverride(string name) =>
        name == "EffectOverride" || name == "EffectOverrideAttribute";
    private static bool IsAcceptDeviation(string name) =>
        name == "AcceptDeviation" || name == "AcceptDeviationAttribute";
}

