        category: "EffectAlgebra",
        defaultSeverity: DiagnosticSeverity.Warning,
        isEnabledByDefault: true,
        description: "§3.3.1 DO-9 + §8.1 release-class：acquire（AddChild/Instantiate/Connect/...）须配 release-class（QueueFree/RemoveChild/Disconnect/...）。L3 仅做调用级近似；真实闭合由运行期 net 判定（§3.3.1）。本近似为方法内 flow-insensitive 扫描，跨方法/跨对象配对可能静默漏报（见类注释 OPEN-2）。");

    public override ImmutableArray<DiagnosticDescriptor> SupportedDiagnostics { get; } =
        ImmutableArray.Create(MissingReleaseForAcquire);

